def encode_list(list1):
    """Write a function to reflect the run-length encoding from a list."""
    if not list1:
        return []
    result = []
    current = list1[0]
    count = 1
    for item in list1[1:]:
        if item == current:
            count += 1
        else:
            result.append([count, current])
            current = item
            count = 1
    result.append([count, current])
    return result
